(ns futon3c.diagramprover.causal.open-theory-export-test
  (:require [clojure.test :refer [deftest is testing]]
            [futon3c.diagramprover.causal.open-theory-export :as export]))

(def fixture-path
  "test/futon3c/diagramprover/causal/fixtures/open-theory-glue.json")

(deftest public-export-is-derived-and-pins-the-glue-boundary
  (let [artifact (export/export-value)]
    (is (= (slurp fixture-path) (export/export-json))
        "the committed artifact is generated by the real glue implementation")
    (is (= "futon3c.open-theory-glue/v1" (get artifact "schema")))
    (is (= [["shared"] ["shared"]]
           (mapv #(get % "interface") (get artifact "theories"))))
    (is (= [{"from" "source", "to" "shared"}
            {"from" "shared", "to" "result"}]
           (get-in artifact ["glue" "arrows"])))
    (is (= {"shared" "source", "result" "shared"}
           (get-in artifact ["glue" "mechanisms"])))
    (is (= {"result" "consumer", "shared" "producer"}
           (get-in artifact ["glue" "owners"])))
    (is (= ["source"] (get-in artifact ["glue" "inputs"])))
    (testing "removing the consumer's interface declaration is refused"
      (is (= {"details" {"shared" ["consumer"]}
              "glued" false
              "reason" "undeclared-sharing"}
             (get artifact "without-declared-interface"))))
    (testing "the implementation warrants union-DAG construction, not sequential equality"
      (is (= {"kind" "validated-union-dag"
              "sequential-composition-equality" "not-defined-by-this-implementation"}
             (get artifact "claim"))))))
